package org.springframework.samples.petclinic.rest.validation;

/**
 * Normalizes and validates owner telephone numbers.
 */
public final class OwnerTelephone {

    public static final int REQUIRED_DIGITS = 10;

    private OwnerTelephone() {
    }

    /**
     * Strips every non-digit character and requires exactly {@value #REQUIRED_DIGITS} digits to remain.
     *
     * @param telephone the telephone number as supplied in the request
     * @return the normalized {@value #REQUIRED_DIGITS}-digit telephone number
     * @throws InvalidTelephoneException if the number does not contain exactly {@value #REQUIRED_DIGITS} digits
     */
    public static String normalize(String telephone) {
        String digits = telephone.replaceAll("\\D", "");
        if (digits.length() != REQUIRED_DIGITS) {
            throw new InvalidTelephoneException(telephone);
        }
        return digits;
    }

    /**
     * @param telephone the telephone number as supplied in the request
     * @throws InvalidTelephoneException if the number contains anything other than digits
     */
    public static void requireDigitsOnly(String telephone) {
        if (telephone != null && !telephone.chars().allMatch(Character::isDigit)) {
            throw new InvalidTelephoneException(telephone);
        }
    }
}
package org.springframework.samples.petclinic.rest.validation;

import jakarta.validation.Constraint;
import jakarta.validation.Payload;
import java.lang.annotation.*;

@Target({ ElementType.FIELD })
@Retention(RetentionPolicy.RUNTIME)
@Constraint(validatedBy = PetAgeValidator.class)
@Documented
public @interface PetAgeValidation {

    String message() default "Birth date must not be in the future or older than 50 years";

    Class<?>[] groups() default {};

    Class<? extends Payload>[] payload() default {};
}package org.springframework.samples.petclinic.rest.validation;

import java.time.LocalDate;

import jakarta.validation.ConstraintValidator;
import jakarta.validation.ConstraintValidatorContext;

public class PetAgeValidator implements ConstraintValidator<PetAgeValidation, LocalDate> {

    @Override
    public boolean isValid(LocalDate birthDate, ConstraintValidatorContext context) {

        if (birthDate == null) {
            return true; 
        }

        LocalDate today = LocalDate.now();

        if (birthDate.isAfter(today)) {
            context.disableDefaultConstraintViolation();
            context.buildConstraintViolationWithTemplate(
                "Birth date cannot be in the future"
            ).addConstraintViolation();
            return false;
        }

        if (birthDate.isBefore(today.minusYears(50))) {
            context.disableDefaultConstraintViolation();
            context.buildConstraintViolationWithTemplate(
                "Birth date cannot be older than 50 years"
            ).addConstraintViolation();
            return false;
        }

        return true;
    }
}package org.springframework.samples.petclinic.rest.validation;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Determines which of the fields required to create an owner are missing or blank.
 */
public final class RequiredOwnerFields {

    private RequiredOwnerFields() {
    }

    /**
     * @param owner the owner fields from the request body
     * @return names of required fields that are missing or blank, in declaration order; empty if none
     */
    public static List<String> missingFields(OwnerFieldsDto owner) {
        Map<String, String> required = new LinkedHashMap<>();
        required.put("firstName", owner.getFirstName());
        required.put("lastName", owner.getLastName());
        required.put("address", owner.getAddress());
        required.put("city", owner.getCity());
        required.put("telephone", owner.getTelephone());
        List<String> missing = new ArrayList<>();
        required.forEach((field, value) -> {
            if (value == null || value.isBlank()) {
                missing.add(field);
            }
        });
        return missing;
    }
}
